__global__ void rms_norm_kernel(
    const float* x,
    float* out,
    const float eps,
    const int total_elements,
    const int feature_dim
) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total_elements) return;

    // Calculate position within feature dimension
    const int pos_in_feature = idx % feature_dim;
    const int group_idx = idx / feature_dim;

    // For position pos_in_feature, load all elements in the feature group
    const int offset = group_idx * feature_dim;

    // Use shared memory to accumulate sum of squares
    __shared__ float s_sum;

    // Each thread computes its local sum for its position in the feature
    float local_val = x[idx];
    float local_squared = local_val * local_val;

    // First thread initializes shared sum
    if (threadIdx.x == 0) {
        s_sum = 0.0f;
    }
    __syncthreads();

    // Atomic add to shared sum (better than full reduction for this case)
    atomicAdd(&s_sum, local_squared);
    __syncthreads();

    // Read RMS value from shared memory
    const float rms_val = s_sum / feature_dim + eps;
    const float inv_rms = rsqrtf(rms_val);

    // Apply normalization
    out[idx] = local_val * inv_rms;
